window.AUTH=window.AUTH||{};window.AUTH["11-159"]={"d":"11-159","id":"2011/11-159","n":"Astrue v. Capato","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the petitioner","date":"","url":"https://www.justice.gov/osg/media/196866/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/astrue-v-capato-brief-merits","n":60}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep566/usrep566541/usrep566541.pdf","tr":true,"items":[{"t":"case","label":"Auer v. Robbins","cite":"519 U.S. 452","y":1997,"id":"1996/95-897","sc":1,"sum":"Authored by Justice Antonin Scalia, the Court ruled that sergeants and lieutenants are exempt as salaried employees from the federal Fair Labor Standards Act. The justices rejected the argument that the possibility of suspension without pay moves the officers out of the exempt category.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Barnhart v. Walton","cite":"535 U.S. 212","y":2002,"id":"2001/00-1937","sc":1,"op":1,"sum":"The Court held that the Social Security Administration's interpretations of the statute fell within its lawful interpretative authority.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Beeler v. Astrue","cite":"651 F.3d 954","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/651/954/","op":2,"by":{"0":"13, 14, 19, 24"}},{"t":"case","label":"Chevron U.S.A. Inc. v. NRDC","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":4,"ar":2,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"6, 24"}},{"t":"case","label":"Cleland v. OPM","cite":"984 F.2d 1193","y":1993,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/984/1193/","sum":"Holding that grandchildren are not entitled to survivorship benefits under the civil-service retirement program, 5 U.S.C. 8341(e)(2), because they are not specifically identified in that statute.","sumSrc":"brief:0","by":{"0":"12"}},{"t":"case","label":"Conlon ex rel. Conlon v. Heckler","cite":"719 F.2d 788","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/719/788/","by":{"0":"11"}},{"t":"case","label":"De Sylva v. Ballentine","cite":"351 U.S. 570","y":1956,"id":"1955/529","sc":1,"sum":"The Copyright Act grants to the author, \"or the widow, widower, or children of the author, if the author be not living,\" the right of renewal of a copyright for a further 28-year term after the expiration of the original 28-year term.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Gainey v. Flemming","cite":"279 F.2d 56","y":1960,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/279/56/","by":{"0":"17"}},{"t":"case","label":"Gillett-Netting v. Barnhart","cite":"371 F.3d 593","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/371/593/","op":1,"by":{"0":"14, 16"}},{"t":"case","label":"Hobby v. Burke","cite":"227 F.2d 932","y":1955,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/227/932/","by":{"0":"17"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"by":{"0":"24"}},{"t":"case","label":"Mansell v. Mansell","cite":"490 U.S. 581","y":1989,"id":"1988/87-201","sc":1,"sum":"The Court held that the federal Uniformed Services Former Spouses' Protection Act exempted that portion of the retirement pay that a service member waived in order to receive disability benefits from the amount divisible upon divorce.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Mathews v. Lucas","cite":"427 U.S. 492","y":1976,"id":"1975/75-88","sc":1,"op":2,"sum":"The Social Security Act provides that a child of an individual who died fully insured under the Act, is entitled to surviving child's benefits if the child is under 18, or a student under 22, and was dependent at the time of the parent's death. A child is considered dependent if the insured parent was living with him or contributed to the child's support at the time of death. Certain children, however, need not …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 20, 21"}},{"t":"case","label":"Pioneer Inv. Servs. Co. v. Brunswick Assoc. Ltd. P’ship","cite":"507 U.S. 380","y":1993,"id":"1992/91-1695","sc":1,"sum":"As unsecured creditors of petitioner-a company seeking relief under Chapter 11 of the Bankruptcy Code-respondents were required to file proofs of claim with the Bankruptcy Court before the deadline, or bar date, established by that court. An August 3, 1989, bar date was included in a \"Notice for Meeting of Creditors\" received from the court by Mark Berlin, an official for respondents. Respondents' attorney was …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10"}},{"t":"case","label":"Robles v. Folsom","cite":"239 F.2d 562","y":1956,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/239/562/","by":{"0":"17"}},{"t":"case","label":"Schafer v. Astrue","cite":"641 F.3d 49","y":2011,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/641/49/","op":3,"sum":"Observing that “it is not at all unusual for Congress to refer explicitly only to one section even though some of that section’s terms are given their full import by another, unmentioned section”.","sumSrc":"brief:0","by":{"0":"passim"}},{"t":"case","label":"Skidmore v. Swift & Co.","cite":"323 U.S. 134","y":1944,"id":"1940-1955/12","sc":1,"sum":"The Court held that there was no reason that time spent waiting could not also be time spent working, especially in cases in which the conditions of employment involve waiting time. Although it can be difficult to determine the facts of a case and whether the activity in question constitutes work, Congress granted the courts the authority to do so.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Talk Am., Inc. v. Michigan Bell Tel. Co.","cite":"131 S. Ct. 2254","y":2011,"id":"2010/10-313","sc":1,"sum":"The Court held that federal law requires local telephone companies to allow new competitors in their markets to link to their existing networks through connecting wires at low, government-regulated rates.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"United States v. Bestfoods","cite":"524 U.S. 51","y":1998,"id":"1997/97-454","sc":1,"sum":"But a corporate parent that actively participated in, and exercised control over, the operations of the facility itself may be held directly liable in its own right as an operator of the facility.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"United States v. Morrison","cite":"529 U.S. 598","y":2000,"id":"1999/99-5","sc":1,"sum":"The Court found that sections of the Violence Against Women Act were unconstitutional under the Commerce Clause.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"United States v. Ron Pair Enters., Inc.","cite":"489 U.S. 235","y":1989,"id":"1988/87-1043","sc":1,"sum":"Section 506(b) entitles a creditor to receive postpetition interest on a nonconsensual oversecured claim allowed in a bankruptcy proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Walters v. Metropolitan Educ. Enters. Inc.","cite":"519 U.S. 202","y":1997,"id":"1996/95-259","sc":1,"sum":"Authored by Justice Antonin Scalia, the Court ruled that the ultimate touchstone under Title VII of the Civil Rights Act of 1964 is whether an employer has employment relationships with 15 or more individuals for each working day in 20 or more weeks during the year in question.","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"Washington State Dep’t of Soc. & Health Servs. v. Guardianship Estate of Keffeler","cite":"537 U.S. 371","y":2003,"id":"2002/01-1420","sc":1,"sum":"The Court held that the state's use of the Social Security benefits to reimburse itself does not violate the Social Security Act's anti-attachment provision.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"usc","label":"42 U.S.C. § 9601","url":"https://www.law.cornell.edu/uscode/text/42/9601","subs":["(20)(A)(ii)"],"by":{"0":"11"}},{"t":"law","label":"Pub. L. No. 89-97","url":"https://www.govinfo.gov/link/statute/79/409","by":{"0":"17"}},{"t":"usc","label":"42 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/42/401","stext":{"head":"§401. Trust Funds","paras":[[0,"(a) Federal Old-Age and Survivors Insurance Trust Fund"],[0,"There is hereby created on the books of the Treasury of the United States a trust fund to be known as the \"Federal Old-Age and Survivors Insurance Trust Fund\". The Federal Old-Age and Survivors Insurance Trust Fund shall consist of the securities held by the Secretary of the Treasury for the Old-Age Reserve Account and the amount standing to the credit of the Old-Age Reserve Account on the books of the Treasury on January 1, 1940, which securities and amount the Secretary of the Treasury is authorized and directed to transfer to the Federal Old-Age and Survivors Insurance Trust Fund, and, in addition, such gifts and bequests as may be made as provided in subsection (i)(1), and such amounts as may be appropriated to, or deposited in, the Federal Old-Age and Survivors Insurance Trust Fund as hereinafter provided. There is hereby appropriated to the Federal Old-Age and Survivors Insurance Trust Fund for the fiscal year ending June 30, 1941, and for each fiscal year thereafter, out of any moneys in the Treasury not otherwise appropriated, amounts equivalent to 100 per centum of—"],[1,"(1) the taxes (including interest, penalties, and additions to the taxes) received under subchapter A of chapter 9 of the Internal Revenue Code of 1939 (and covered into the Treasury) which are deposited into the Treasury by collectors of internal revenue before January 1, 1951; and"],[1,"(2) the taxes certified each month by the Commissioner of Internal Revenue as taxes received under subchapter A of chapter 9 of such Code which are deposited into the Treasury by collectors of internal revenue after December 31, 1950, and before January 1, 1953, with respect to assessments of such taxes made before January 1, 1951; and"],[1,"(3) the taxes imposed by subchapter A of chapter 9 of such Code with respect to wages (as defined in section 1426 of such Code), and by chapter 21 (other than sections 3101(b) and 3111(b)) of the Internal Revenue Code of 1954 with respect to wages (as defined in section 3121 of such Code) reported to the Commissioner of Internal Revenue pursuant to section 1420(c) of the Internal Revenue Code of 1939 after December 31, 1950, or to the Secretary of the Treasury or his delegates pursuant to subtitle F of the Internal Revenue Code of 1954 after December 31, 1954, as determined by the Secretary of the Treasury by applying the applicable rates of tax under such subchapter or chapter 21 (other than sections 3101(b) and 3111(b)) to such wages, which wages shall be certified by the Commissioner of Social Security on the basis of the records of wages established and maintained by such Commissioner in accordance with such reports, less the amounts specified in clause (1) of subsection (b) of this section; and"],[1,"(4) the taxes imposed by subchapter E of chapter 1 of the Internal Revenue Code of 1939, with respect to self-employment income (as defined in section 481 of such Code), and by chapter 2 (other than section 1401(b)) of the Internal Revenue Code of 1954 with respect to self-employment income (as defined in section 1402 of such Code) reported to the Commissioner of Internal Revenue on tax returns under such subchapter or to the Secretary of the Treasury or his delegate on tax returns under subtitle F of such Code, as determined by the Secretary of the Treasury by applying the applicable rate of tax under such subchapter or chapter (other than section 1401(b)) to such self-employment income, which self-employment income shall be certified by the Commissioner of Social Security on the basis of the records of self-employment income established and maintained by the Commissioner of Social Security in accordance with such returns, less the amounts specified in clause (2) of subsection (b) of this section."],[0,"The amounts appropriated by clauses (3) and (4) of this subsection shall be transferred from time to time from the general fund in the Treasury to the Federal Old-Age and Survivors Insurance Trust Fund, and the amounts appropriated by clauses (1) and (2) of subsection (b) shall be transferred from time to time from the general fund in the Treasury to the Federal Disability Insurance Trust Fund, such amounts to be determined on the basis of estimates by the Secretary of the Treasury of the taxes, specified in clauses (3) and (4) of this subsection, paid to or deposited into the Treasury; and proper adjustments shall be made in amounts subsequently transferred to the extent prior estimates were in excess of or were less than the taxes specified in such clauses (3) and (4) of this subsection. All amounts transferred to either Trust Fund under the preceding sentence shall be invested by the Managing Trustee in the same manner and to the same extent as the other assets of such Trust Fund. Notwithstanding the preceding sentence, in any case in which the Secretary of the Treasury determines that the assets of either such Trust Fund would otherwise be inadequate to meet such Fund's obligations for any month, the Secretary of the Treasury shall transfer to such Trust Fund on the first day of such month the amount which would have been transferred to such Fund under this section as in effect on October 1, 1990; and such Trust Fund shall pay interest to the general fund on the amount so transferred on the first day of any month at a rate (calculated on a daily basis, and applied against the difference between the amount so transferred on such first day and the amount which would have been transferred to the Trust Fund up to that day under the procedures in effect on January 1, 1983) equal to the rate earned by the investments of such Fund in the same month under subsection (d)."],[0,"(b) Federal Disability Insurance Trust Fund"],[0,"There is hereby created on the books of the Treasury of the United States a trust fund to be known as the \"Federal Disability Insurance Trust Fund\". The Federal Disability Insurance Trust Fund shall consist of such gifts and bequests as may be made as provided in subsection (i)(1), and such amounts as may be appropriated to, or deposited in, such fund as provided in this section. There is hereby appropriated to the Federal Disability Insurance Trust Fund for the fiscal year ending June 30, 1957, and for each fiscal year thereafter, out of any moneys in the Treasury not otherwise appropriated, amounts equivalent to 100 per centum of—"],[1,"(1)(A) ½ of 1 per centum of the wages (as defined in section 3121 of the Internal Revenue Code of 1954) paid after December 31, 1956, and before January 1, 1966, and reported to the Secretary of the Treasury or his delegate pursuant to subtitle F of the Internal Revenue Code of 1954, (B) 0.70 of 1 per centum of the wages (as so defined) paid after December 31, 1965, and before January 1, 1968, and so reported, (C) 0.95 of 1 per centum of the wages (as so defined) paid after December 31, 1967, and before January 1, 1970, and so reported, (D) 1.10 per centum of the wages (as so defined) paid after December 31, 1969, and before January 1, 1973, and so reported, (E) 1.1 per centum of the wages (as so defined) paid after December 31, 1972, and before January 1, 1974, and so reported, (F) 1.15 per centum of the wages (as so defined) paid after December 31, 1973, and before January 1, 1978, and so reported, (G) 1.55 per centum of the wages (as so defined) paid after December 31, 1977, and before January 1, 1979, and so reported, (H) 1.50 per centum of the wages (as so defined) paid after December 31, 1978, and before January 1, 1980, and so reported, (I) 1.12 per centum of the wages (as so defined) paid after December 31, 1979, and before January 1, 1981, and so reported, (J) 1.30 per centum of the wages (as so defined) paid after December 31, 1980, and before January 1, 1982, and so reported, (K) 1.65 per centum of the wages (as so defined) paid after December 31, 1981, and before January 1, 1983, and so reported, (L) 1.25 per centum of the wages (as so defined) paid after December 31, 1982, and before January 1, 1984, and so reported, (M) 1.00 per centum of the wages (as so defined) paid after December 31, 1983, and before January 1, 1988, and so reported, (N) 1.06 per centum of the wages (as so defined) paid after December 31, 1987, and before January 1, 1990, and so reported, (O) 1.20 per centum of the wages (as so defined) paid after December 31, 1989, and before January 1, 1994, and so reported, (P) 1.88 per centum of the wages (as so defined) paid after December 31, 1993, and before January 1, 1997, and so reported, (Q) 1.70 per centum of the wages (as so defined) paid after December 31, 1996, and before January 1, 2000, and so reported, (R) 1.80 per centum of the wages (as so defined) paid after December 31, 1999, and before January 1, 2016, and so reported, (S) 2.37 per centum of the wages (as so defined) paid after December 31, 2015, and before January 1, 2019, and so reported, and (T) 1.80 per centum of the wages (as so defined) paid after December 31, 2018, and so reported,,1 which wages shall be certified by the Commissioner of Social Security on the basis of the records of wages established and maintained by such Commissioner in accordance with such reports; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/401?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§401. Trust Funds","tname":"The Public Health and Welfare","by":{"0":"2"}},{"t":"usc","label":"42 U.S.C. § 402","url":"https://www.law.cornell.edu/uscode/text/42/402","subs":["(b)(1)","(c)(1)(1940)","(c)(1)","(d)","(d)(1)","(e)(1)","(f)(1)"],"stext":{"head":"§402. Old-age and survivors insurance benefit payments","paras":[[0,"(a) Old-age insurance benefits"],[0,"Every individual who—"],[1,"(1) is a fully insured individual (as defined in section 414(a) of this title),"],[1,"(2) has attained age 62, and"],[1,"(3) has filed application for old-age insurance benefits or was entitled to disability insurance benefits for the month preceding the month in which he attained retirement age (as defined in section 416(l) of this title),"],[0,"shall be entitled to an old-age insurance benefit for each month, beginning with—"],[1,"(A) in the case of an individual who has attained retirement age (as defined in section 416(l) of this title), the first month in which such individual meets the criteria specified in paragraphs (1), (2), and (3), or"],[1,"(B) in the case of an individual who has attained age 62, but has not attained retirement age (as defined in section 416(l) of this title), the first month throughout which such individual meets the criteria specified in paragraphs (1) and (2) (if in that month he meets the criterion specified in paragraph (3)),"],[0,"and ending with the month preceding the month in which he dies. Except as provided in subsection (q) and subsection (w), such individual's old-age insurance benefit for any month shall be equal to his primary insurance amount (as defined in section 415(a) of this title) for such month."],[0,"(b) Wife's insurance benefits"],[0,"(1) The wife (as defined in section 416(b) of this title) and every divorced wife (as defined in section 416(d) of this title) of an individual entitled to old-age or disability insurance benefits, if such wife or such divorced wife—"],[1,"(A) has filed application for wife's insurance benefits,"],[1,"(B)(i) has attained age 62, or"],[1,"(ii) in the case of a wife, has in her care (individually or jointly with such individual) at the time of filing such application a child entitled to a child's insurance benefit on the basis of the wages and self-employment income of such individual,"],[1,"(C) in the case of a divorced wife, is not married, and"],[1,"(D) is not entitled to old-age or disability insurance benefits, or is entitled to old-age or disability insurance benefits based on a primary insurance amount which is less than one-half of the primary insurance amount of such individual,"],[0,"shall (subject to subsection (s)) be entitled to a wife's insurance benefit for each month, beginning with—"],[1,"(i) in the case of a wife or divorced wife (as so defined) of an individual entitled to old-age benefits, if such wife or divorced wife has attained retirement age (as defined in section 416(l) of this title), the first month in which she meets the criteria specified in subparagraphs (A), (B), (C), and (D), or"],[1,"(ii) in the case of a wife or divorced wife (as so defined) of—"],[2,"(I) an individual entitled to old-age insurance benefits, if such wife or divorced wife has not attained retirement age (as defined in section 416(l) of this title), or"],[2,"(II) an individual entitled to disability insurance benefits,"],[1,"the first month throughout which she is such a wife or divorced wife and meets the criteria specified in subparagraphs (B), (C), and (D) (if in such month she meets the criterion specified in subparagraph (A)),"],[0,"whichever is earlier, and ending with the month preceding the month in which any of the following occurs—"],[1,"(E) she dies,"],[1,"(F) such individual dies,"],[1,"(G) in the case of a wife, they are divorced and either (i) she has not attained age 62, or (ii) she has attained age 62 but has not been married to such individual for a period of 10 years immediately before the date the divorce became effective,"],[1,"(H) in the case of a divorced wife, she marries a person other than such individual,"],[1,"(I) in the case of a wife who has not attained age 62, no child of such individual is entitled to a child's insurance benefit,"],[1,"(J) she becomes entitled to an old-age or disability insurance benefit based on a primary insurance amount which is equal to or exceeds one-half of the primary insurance amount of such individual, or"],[1,"(K) such individual is not entitled to disability insurance benefits and is not entitled to old-age insurance benefits."],[0,"(2) Except as provided in subsection (q), such wife's insurance benefit for each month shall be equal to one-half of the primary insurance amount of her husband (or, in the case of a divorced wife, her former husband) for such month."],[0,"(3) In the case of any divorced wife who marries—"],[1,"(A) an individual entitled to benefits under subsection (c), (f), (g), or (h) of this section, or"],[1,"(B) an individual who has attained the age of 18 and is entitled to benefits under subsection (d),"],[0,"such divorced wife's entitlement to benefits under this subsection shall, notwithstanding the provisions of paragraph (1) (but subject to subsection (s)), not be terminated by reason of such marriage."],[0,"(4)(A) Notwithstanding the preceding provisions of this subsection, except as provided in subparagraph (B), the divorced wife of an individual who is not entitled to old-age or disability insurance benefits, but who has attained age 62 and is a fully insured individual (as defined in section 414 of this title), if such divorced wife—"],[1,"(i) meets the requirements of subparagraphs (A) through (D) of paragraph (1), and"],[1,"(ii) has been divorced from such insured individual for not less than 2 years,"],[0,"shall be entitled to a wife's insurance benefit under this subsection for each month, in such amount, and beginning and ending with such months, as determined (under regulations of the Commissioner of Social Security) in the manner otherwise provided for wife's insurance benefits under this subsection, as if such insured individual had become entitled to old-age insurance benefits on the date on which the divorced wife first meets the criteria for entitlement set forth in clauses (i) and (ii)."],[0,"(B) A wife's insurance benefit provided under this paragraph which has not otherwise terminated in accordance with subparagraph (E), (F), (H), or (J) of paragraph (1) shall terminate with the month preceding the first month in which the insured individual is no longer a fully insured individual."],[0,"(c) Husband's insurance benefits"],[0,"(1) The husband (as defined in section 416(f) of this title) and every divorced husband (as defined in section 416(d) of this title) of an individual entitled to old-age or disability insurance benefits, if such husband or such divorced husband—"],[1,"(A) has filed application for husband's insurance benefits,"],[1,"(B)(i) has attained age 62, or"],[1,"(ii) in the case of a husband, has in his care (individually or jointly with such individual) at the time of filing such application a child entitled to a child's insurance benefit on the basis of the wages and self-employment income of such individual,"],[1,"(C) in the case of a divorced husband, is not married, and"],[1,"(D) is not entitled to old-age or disability insurance benefits, or is entitled to old-age or disability insurance benefits based on a primary insurance amount which is less than one-half of the primary insurance amount of such individual,"],[0,"shall (subject to subsection (s)) be entitled to a husband's insurance benefit for each month, beginning with—"],[1,"(i) in the case of a husband or divorced husband (as so defined) of an individual who is entitled to an old-age insurance benefit, if such husband or divorced husband has attained retirement age (as defined in section 416(l) of this title), the first month in which he meets the criteria specified in subparagraphs (A), (B), (C), and (D), or"],[1,"(ii) in the case of a husband or divorced husband (as so defined) of—"],[2,"(I) an individual entitled to old-age insurance benefits, if such husband or divorced husband has not attained retirement age (as defined in section 416(l) of this title), or"],[2,"(II) an individual entitled to disability insurance benefits,"],[1,"the first month throughout which he is such a husband or divorced husband and meets the criteria specified in subparagraphs (B), (C), and (D) (if in such month he meets the criterion specified in subparagraph (A)),"],[0,"whichever is earlier, and ending with the month preceding the month in which any of the following occurs:"],[1,"(E) he dies,"],[1,"(F) such individual dies,"],[1,"(G) in the case of a husband, they are divorced and either (i) he has not attained age 62, or (ii) he has attained age 62 but has not been married to such individual for a period of 10 years immediately before the divorce became effective,"],[1,"(H) in the case of a divorced husband, he marries a person other than such individual,"],[1,"(I) in the case of a husband who has not attained age 62, no child of such individual is entitled to a child's insurance benefit,"],[1,"(J) he becomes entitled to an old-age or disability insurance benefit based on a primary insurance amount which is equal to or exceeds one-half of the primary insurance amount of such individual, or"],[1,"(K) such individual is not entitled to disability insurance benefits and is not entitled to old-age insurance benefits."],[0,"(2) Except as provided in subsection (q), such husband's insurance benefit for each month shall be equal to one-half of the primary insurance amount of his wife (or, in the case of a divorced husband, his former wife) for such month."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/402?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§402. Old-age and survivors insurance benefit payments","tname":"The Public Health and Welfare","by":{"0":"13, 16, 13, 5, 7, 12, 25, 2, 3, 7, 23, 13, 13"}},{"t":"usc","label":"42 U.S.C. § 403","url":"https://www.law.cornell.edu/uscode/text/42/403","subs":["(a)(1)"],"by":{"0":"22"}},{"t":"usc","label":"42 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/42/405","subs":["(a)"],"stext":{"head":"§405. Evidence, procedure, and certification for payments","paras":[[0,"(a) Rules and regulations; procedures"],[0,"The Commissioner of Social Security shall have full power and authority to make rules and regulations and to establish procedures, not inconsistent with the provisions of this subchapter, which are necessary or appropriate to carry out such provisions, and shall adopt reasonable and proper rules and regulations to regulate and provide for the nature and extent of the proofs and evidence and the method of taking and furnishing the same in order to establish the right to benefits hereunder."],[0,"(b) Administrative determination of entitlement to benefits; findings of fact; hearings; investigations; evidentiary hearings in reconsiderations of disability benefit terminations; subsequent applications"],[0,"(1) The Commissioner of Social Security is directed to make findings of fact, and decisions as to the rights of any individual applying for a payment under this subchapter. Any such decision by the Commissioner of Social Security which involves a determination of disability and which is in whole or in part unfavorable to such individual shall contain a statement of the case, in understandable language, setting forth a discussion of the evidence, and stating the Commissioner's determination and the reason or reasons upon which it is based. Upon request by any such individual or upon request by a wife, divorced wife, widow, surviving divorced wife, surviving divorced mother, surviving divorced father, husband, divorced husband, widower, surviving divorced husband, child, or parent who makes a showing in writing that his or her rights may be prejudiced by any decision the Commissioner of Social Security has rendered, the Commissioner shall give such applicant and such other individual reasonable notice and opportunity for a hearing with respect to such decision, and, if a hearing is held, shall, on the basis of evidence adduced at the hearing, affirm, modify, or reverse the Commissioner's findings of fact and such decision. Any such request with respect to such a decision must be filed within sixty days after notice of such decision is received by the individual making such request. The Commissioner of Social Security is further authorized, on the Commissioner's own motion, to hold such hearings and to conduct such investigations and other proceedings as the Commissioner may deem necessary or proper for the administration of this subchapter. In the course of any hearing, investigation, or other proceeding, the Commissioner may administer oaths and affirmations, examine witnesses, and receive evidence. Evidence may be received at any hearing before the Commissioner of Social Security even though inadmissible under rules of evidence applicable to court procedure."],[0,"(2) In any case where—"],[1,"(A) an individual is a recipient of disability insurance benefits, or of child's, widow's, or widower's insurance benefits based on disability,"],[1,"(B) the physical or mental impairment on the basis of which such benefits are payable is found to have ceased, not to have existed, or to no longer be disabling, and"],[1,"(C) as a consequence of the finding described in subparagraph (B), such individual is determined by the Commissioner of Social Security not to be entitled to such benefits,"],[0,"any reconsideration of the finding described in subparagraph (B), in connection with a reconsideration by the Commissioner of Social Security (before any hearing under paragraph (1) on the issue of such entitlement) of the Commissioner's determination described in subparagraph (C), shall be made only after opportunity for an evidentiary hearing, with regard to the finding described in subparagraph (B), which is reasonably accessible to such individual. Any reconsideration of a finding described in subparagraph (B) may be made either by the State agency or the Commissioner of Social Security where the finding was originally made by the State agency, and shall be made by the Commissioner of Social Security where the finding was originally made by the Commissioner of Social Security. In the case of a reconsideration by a State agency of a finding described in subparagraph (B) which was originally made by such State agency, the evidentiary hearing shall be held by an adjudicatory unit of the State agency other than the unit that made the finding described in subparagraph (B). In the case of a reconsideration by the Commissioner of Social Security of a finding described in subparagraph (B) which was originally made by the Commissioner of Social Security, the evidentiary hearing shall be held by a person other than the person or persons who made the finding described in subparagraph (B)."],[0,"(3)(A) A failure to timely request review of an initial adverse determination with respect to an application for any benefit under this subchapter or an adverse determination on reconsideration of such an initial determination shall not serve as a basis for denial of a subsequent application for any benefit under this subchapter if the applicant demonstrates that the applicant, or any other individual referred to in paragraph (1), failed to so request such a review acting in good faith reliance upon incorrect, incomplete, or misleading information, relating to the consequences of reapplying for benefits in lieu of seeking review of an adverse determination, provided by any officer or employee of the Social Security Administration or any State agency acting under section 421 of this title."],[0,"(B) In any notice of an adverse determination with respect to which a review may be requested under paragraph (1), the Commissioner of Social Security shall describe in clear and specific language the effect on possible entitlement to benefits under this subchapter of choosing to reapply in lieu of requesting review of the determination."],[0,"(c) Wage records"],[0,"(1) For the purposes of this subsection—"],[1,"(A) The term \"year\" means a calendar year when used with respect to wages and a taxable year when used with respect to self-employment income."],[1,"(B) The term \"time limitation\" means a period of three years, three months, and fifteen days."],[1,"(C) The term \"survivor\" means an individual's spouse, surviving divorced wife, surviving divorced husband, surviving divorced mother, surviving divorced father, child, or parent, who survives such individual."],[1,"(D) The term \"period\" when used with respect to self-employment income means a taxable year and when used with respect to wages means—"],[2,"(i) a quarter if wages were reported or should have been reported on a quarterly basis on tax returns filed with the Secretary of the Treasury or his delegate under section 6011 of the Internal Revenue Code of 1986 or regulations thereunder (or on reports filed by a State under section 418(e) 1 of this title (as in effect prior to December 31, 1986) or regulations thereunder),"],[2,"(ii) a year if wages were reported or should have been reported on a yearly basis on such tax returns or reports, or"],[2,"(iii) the half year beginning January 1 or July 1 in the case of wages which were reported or should have been reported for calendar year 1937."],[0,"(2)(A) On the basis of information obtained by or submitted to the Commissioner of Social Security, and after such verification thereof as the Commissioner deems necessary, the Commissioner of Social Security shall establish and maintain records of the amounts of wages paid to, and the amounts of self-employment income derived by, each individual and of the periods in which such wages were paid and such income was derived and, upon request, shall inform any individual or his survivor, or the legal representative of such individual or his estate, of the amounts of wages and self-employment income of such individual and the periods during which such wages were paid and such income was derived, as shown by such records at the time of such request."],[0,"(B)(i) In carrying out the Commissioner's duties under subparagraph (A) and subparagraph (F), the Commissioner of Social Security shall take affirmative measures to assure that social security account numbers will, to the maximum extent practicable, be assigned to all members of appropriate groups or categories of individuals by assigning such numbers (or ascertaining that such numbers have already been assigned):"],[1,"(I) to aliens at the time of their lawful admission to the United States either for permanent residence or under other authority of law permitting them to engage in employment in the United States and to other aliens at such time as their status is so changed as to make it lawful for them to engage in such employment;"],[1,"(II) to any individual who is an applicant for or recipient of benefits under any program financed in whole or in part from Federal funds including any child on whose behalf such benefits are claimed by another person; and"],[1,"(III) to any other individual when it appears that he could have been but was not assigned an account number under the provisions of subclauses (I) or (II) but only after such investigation as is necessary to establish to the satisfaction of the Commissioner of Social Security, the identity of such individual, the fact that an account number has not already been assigned to such individual, and the fact that such individual is a citizen or a noncitizen who is not, because of his alien status, prohibited from engaging in employment;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/405?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§405. Evidence, procedure, and certification for payments","tname":"The Public Health and Welfare","by":{"0":"24"}},{"t":"usc","label":"42 U.S.C. § 409","url":"https://www.law.cornell.edu/uscode/text/42/409","subs":["(k)(1940)","(m)(1940)"],"stext":{"head":"§409. \"Wages\" defined","paras":[[0,"(a) In general"],[0,"For the purposes of this subchapter, the term \"wages\" means remuneration paid prior to 1951 which was wages for the purposes of this subchapter under the law applicable to the payment of such remuneration, and remuneration paid after 1950 for employment, including the cash value of all remuneration (including benefits) paid in any medium other than cash; except that, in the case of remuneration paid after 1950, such term shall not include—"],[1,"(1)(A) That part of remuneration which, after remuneration (other than remuneration referred to in the succeeding subsections of this section) equal to $3,600 with respect to employment has been paid to an individual during any calendar year prior to 1955, is paid to such individual during such calendar year;"],[1,"(B) That part of remuneration which, after remuneration (other than remuneration referred to in the succeeding subsections of this section) equal to $4,200 with respect to employment has been paid to an individual during any calendar year after 1954 and prior to 1959, is paid to such individual during such calendar year;"],[1,"(C) That part of remuneration which, after remuneration (other than remuneration referred to in the succeeding subsections of this section) equal to $4,800 with respect to employment has been paid to an individual during any calendar year after 1958 and prior to 1966, is paid to such individual during such calendar year;"],[1,"(D) That part of remuneration which, after remuneration (other than remuneration referred to in the succeeding subsections of this section) equal to $6,600 with respect to employment has been paid to an individual during any calendar year after 1965 and prior to 1968, is paid to such individual during such calendar year;"],[1,"(E) That part of remuneration which, after remuneration (other than remuneration referred to in the succeeding subsections of this section) equal to $7,800 with respect to employment has been paid to an individual during any calendar year after 1967 and prior to 1972, is paid to such individual during such calendar year;"],[1,"(F) That part of remuneration which, after remuneration (other than remuneration referred to in the succeeding subsections of this section) equal to $9,000 with respect to employment has been paid to an individual during any calendar year after 1971 and prior to 1973, is paid to such individual during any such calendar year;"],[1,"(G) That part of remuneration which, after remuneration (other than remuneration referred to in the succeeding subsections of this section) equal to $10,800 with respect to employment has been paid to an individual during any calendar year after 1972 and prior to 1974, is paid to such individual during such calendar year;"],[1,"(H) That part of remuneration which, after remuneration (other than remuneration referred to in the succeeding subsections of this section) equal to $13,200 with respect to employment has been paid to an individual during any calendar year after 1973 and prior to 1975, is paid to such individual during such calendar year;"],[1,"(I) That part of remuneration which, after remuneration (other than remuneration referred to in the succeeding subsections of this section) equal to the contribution and benefit base (determined under section 430 of this title) with respect to employment has been paid to an individual during any calendar year after 1974 with respect to which such contribution and benefit base is effective, is paid to such individual during such calendar year;"],[1,"(2) The amount of any payment (including any amount paid by an employer for insurance or annuities, or into a fund, to provide for any such payment) made to, or on behalf of, an employee or any of his dependents under a plan or system established by an employer which makes provision for his employees generally (or for his employees generally and their dependents) or for a class or classes of his employees (or for a class or classes of his employees and their dependents), on account of (A) sickness or accident disability (but, in the case of payments made to an employee or any of his dependents, this clause shall exclude from the term \"wages\" only payments which are received under a workmen's compensation law), or (B) medical or hospitalization expenses in connection with sickness or accident disability, or (C) death, except that this subsection does not apply to a payment for group-term life insurance to the extent that such payment is includible in the gross income of the employee under the Internal Revenue Code of 1986;"],[1,"(3) Any payment on account of sickness or accident disability, or medical or hospitalization expenses in connection with sickness or accident disability, made by an employer to, or on behalf of, an employee after the expiration of six calendar months following the last calendar month in which the employee worked for such employer;"],[1,"(4) Any payment made to, or on behalf of, an employee or his beneficiary (A) from or to a trust exempt from tax under section 165(a) of the Internal Revenue Code of 1939 at the time of such payment or, in the case of a payment after 1954, under sections 401 and 501(a) of the Internal Revenue Code of 1954 or the Internal Revenue Code of 1986, unless such payment is made to an employee of the trust as remuneration for services rendered as such employee and not as a beneficiary of the trust, or (B) under or to an annuity plan which, at the time of such payment, meets the requirements of section 165(a)(3), (4), (5), and (6) of the Internal Revenue Code of 1939 or, in the case of a payment after 1954 and prior to 1963, the requirements of section 401(a)(3), (4), (5), and (6) of the Internal Revenue Code of 1954, or (C) under or to an annuity plan which, at the time of any such payment after 1962, is a plan described in section 403(a) of the Internal Revenue Code of 1986, or (D) under or to a bond purchase plan which, at the time of any such payment after 1962, is a qualified bond purchase plan described in section 405(a) of the Internal Revenue Code of 1954 (as in effect before July 18, 1984), or (E) under or to an annuity contract described in section 403(b) of the Internal Revenue Code of 1986, other than a payment for the purchase of such contract which is made by reason of a salary reduction agreement (whether evidenced by a written instrument or otherwise), or (F) under or to an exempt governmental deferred compensation plan (as defined in section 3121(v)(3) of such Code), or (G) to supplement pension benefits under a plan or trust described in any of the foregoing provisions of this subsection to take into account some portion or all of the increase in the cost of living (as determined by the Secretary of Labor) since retirement but only if such supplemental payments are under a plan which is treated as a welfare plan under section 3(2)(B)(ii) of the Employee Retirement Income Security Act of 1974 [29 U.S.C. 1002(2)(B)(ii)], or (H) under a simplified employee pension (as defined in section 408(k)(1) of such Code), other than any contributions described in section 408(k)(6) of such Code, or (I) under a cafeteria plan (within the meaning of section 125 of the Internal Revenue Code of 1986) if such payment would not be treated as wages without regard to such plan and it is reasonable to believe that (if section 125 applied for purposes of this section) section 125 would not treat any wages as constructively received; or (J) under an arrangement to which section 408(p) of such Code applies, other than any elective contributions under paragraph (2)(A)(i) thereof; or (K) under a plan described in section 457(e)(11)(A)(ii) of the Internal Revenue Code of 1986 and maintained by an eligible employer (as defined in section 457(e)(1) of such Code);"],[1,"(5) The payment by an employer (without deduction from the remuneration of the employee)—"],[2,"(A) of the tax imposed upon an employee under section 3101 of the Internal Revenue Code of 1986, or"],[2,"(B) of any payment required from an employee under a State unemployment compensation law,"],[1,"with respect to remuneration paid to an employee for domestic service in a private home of the employer or for agricultural labor;"],[1,"(6)(A) Remuneration paid in any medium other than cash to an employee for service not in the course of the employer's trade or business or for domestic service in a private home of the employer;"],[1,"(B) Cash remuneration paid by an employer in any calendar year to an employee for domestic service in a private home of the employer (including domestic service on a farm operated for profit), if the cash remuneration paid in such year by the employer to the employee for such service is less than the applicable dollar threshold (as defined in section 3121(x) of the Internal Revenue Code of 1986) for such year;"],[1,"(C) Cash remuneration paid by an employer in any calendar year to an employee for service not in the course of the employer's trade or business, if the cash remuneration paid in such year by the employer to the employee for such service is less than $100. As used in this paragraph, the term \"service not in the course of the employer's trade or business\" does not include domestic service in a private home of the employer and does not include service described in section 410(f)(5) of this title;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/409?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§409. \"Wages\" defined","tname":"The Public Health and Welfare","by":{"0":"16, 16"}},{"t":"usc","label":"42 U.S.C. § 416","url":"https://www.law.cornell.edu/uscode/text/42/416","subs":["(b)","(e)","(e)(1)","(e)(2)","(e)(3)","(h)","(h)(1)(A)","(h)(1)(A)(i)","(h)(1)(A)(ii)","(h)(2)","(h)(2)(A)","(h)(2)(B)","(h)(3)","(h)(3)(C)","(h)(3)(C)(i)","(h)(3)(C)(ii)"],"stext":{"head":"§416. Additional definitions","paras":[[0,"For the purposes of this subchapter—"],[0,"(a) Spouse; surviving spouse"],[0,"(1) The term \"spouse\" means a wife as defined in subsection (b) or a husband as defined in subsection (f)."],[0,"(2) The term \"surviving spouse\" means a widow as defined in subsection (c) or a widower as defined in subsection (g)."],[0,"(b) Wife"],[0,"The term \"wife\" means the wife of an individual, but only if she (1) is the mother of his son or daughter, (2) was married to him for a period of not less than one year immediately preceding the day on which her application is filed, or (3) in the month prior to the month of her marriage to him (A) was entitled to, or on application therefor and attainment of age 62 in such prior month would have been entitled to, benefits under subsection (b), (e), or (h) of section 402 of this title, (B) had attained age eighteen and was entitled to, or on application therefor would have been entitled to, benefits under subsection (d) of such section (subject, however, to section 402(s) of this title), or (C) was entitled to, or upon application therefor and attainment of the required age (if any) would have been entitled to, a widow's, child's (after attainment of age 18), or parent's insurance annuity under section 231a of title 45. For purposes of clause (2), a wife shall be deemed to have been married to an individual for a period of one year throughout the month in which occurs the first anniversary of her marriage to such individual. For purposes of subparagraph (C) of section 402(b)(1) of this title, a divorced wife shall be deemed not to be married throughout the month in which she becomes divorced."],[0,"(c) Widow"],[0,"(1) The term \"widow\" (except when used in the first sentence of section 402(i) of this title) means the surviving wife of an individual, but only if (A) she is the mother of his son or daughter, (B) she legally adopted his son or daughter while she was married to him and while such son or daughter was under the age of eighteen, (C) he legally adopted her son or daughter while she was married to him and while such son or daughter was under the age of eighteen, (D) she was married to him at the time both of them legally adopted a child under the age of eighteen, (E) except as provided in paragraph (2), she was married to him for a period of not less than nine months immediately prior to the day on which he died, or (F) in the month prior to the month of her marriage to him (i) she was entitled to, or on application therefor and attainment of age 62 in such prior month would have been entitled to, benefits under subsection (b), (e), or (h) of section 402 of this title, (ii) she had attained age eighteen and was entitled to, or on application therefor would have been entitled to, benefits under subsection (d) of such section (subject, however, to section 402(s) of this title), or (iii) she was entitled to, or upon application therefor and attainment of the required age (if any) would have been entitled to, a widow's, child's (after attainment of age 18), or parent's insurance annuity under section 231a of title 45."],[0,"(2) The requirements of paragraph (1)(E) in connection with the surviving wife of an individual shall be treated as satisfied if—"],[1,"(A) the individual had been married prior to the individual's marriage to the surviving wife,"],[1,"(B) the prior wife was institutionalized during the individual's marriage to the prior wife due to mental incompetence or similar incapacity,"],[1,"(C) during the period of the prior wife's institutionalization, the individual would have divorced the prior wife and married the surviving wife, but the individual did not do so because such divorce would have been unlawful, by reason of the prior wife's institutionalization, under the laws of the State in which the individual was domiciled at the time (as determined based on evidence satisfactory to the Commissioner of Social Security),"],[1,"(D) the prior wife continued to remain institutionalized up to the time of her death, and"],[1,"(E) the individual married the surviving wife within 60 days after the prior wife's death."],[0,"(d) Divorced spouses; divorce"],[0,"(1) The term \"divorced wife\" means a woman divorced from an individual, but only if she had been married to such individual for a period of 10 years immediately before the date the divorce became effective."],[0,"(2) The term \"surviving divorced wife\" means a woman divorced from an individual who has died, but only if she had been married to the individual for a period of 10 years immediately before the date the divorce became effective."],[0,"(3) The term \"surviving divorced mother\" means a woman divorced from an individual who has died, but only if (A) she is the mother of his son or daughter, (B) she legally adopted his son or daughter while she was married to him and while such son or daughter was under the age of 18, (C) he legally adopted her son or daughter while she was married to him and while such son or daughter was under the age of 18, or (D) she was married to him at the time both of them legally adopted a child under the age of 18."],[0,"(4) The term \"divorced husband\" means a man divorced from an individual, but only if he had been married to such individual for a period of 10 years immediately before the date the divorce became effective."],[0,"(5) The term \"surviving divorced husband\" means a man divorced from an individual who has died, but only if he had been married to the individual for a period of 10 years immediately before the divorce became effective."],[0,"(6) The term \"surviving divorced father\" means a man divorced from an individual who has died, but only if (A) he is the father of her son or daughter, (B) he legally adopted her son or daughter while he was married to her and while such son or daughter was under the age of 18, (C) she legally adopted his son or daughter while he was married to her and while such son or daughter was under the age of 18, or (D) he was married to her at the time both of them legally adopted a child under the age of 18."],[0,"(7) The term \"surviving divorced parent\" means a surviving divorced mother as defined in paragraph (3) of this subsection or a surviving divorced father as defined in paragraph (6)."],[0,"(8) The terms \"divorce\" and \"divorced\" refer to a divorce a vinculo matrimonii."],[0,"(e) Child"],[0,"The term \"child\" means (1) the child or legally adopted child of an individual, (2) a stepchild who has been such stepchild for not less than one year immediately preceding the day on which application for child's insurance benefits is filed or (if the insured individual is deceased) not less than nine months immediately preceding the day on which such individual died, and (3) a person who is the grandchild or stepgrandchild of an individual or his spouse, but only if (A) there was no natural or adoptive parent (other than such a parent who was under a disability, as defined in section 423(d) of this title) of such person living at the time (i) such individual became entitled to old-age insurance benefits or disability insurance benefits or died, or (ii) if such individual had a period of disability which continued until such individual became entitled to old-age insurance benefits or disability insurance benefits, or died, at the time such period of disability began, or (B) such person was legally adopted after the death of such individual by such individual's surviving spouse in an adoption that was decreed by a court of competent jurisdiction within the United States and such person's natural or adopting parent or stepparent was not living in such individual's household and making regular contributions toward such person's support at the time such individual died. For purposes of clause (1), a person shall be deemed, as of the date of death of an individual, to be the legally adopted child of such individual if such person was either living with or receiving at least one-half of his support from such individual at the time of such individual's death and was legally adopted by such individual's surviving spouse after such individual's death but only if (A) proceedings for the adoption of the child had been instituted by such individual before his death, or (B) such child was adopted by such individual's surviving spouse before the end of two years after (i) the day on which such individual died or (ii) August 28, 1958. For purposes of clause (2), a person who is not the stepchild of an individual shall be deemed the stepchild of such individual if such individual was not the mother or adopting mother or the father or adopting father of such person and such individual and the mother or adopting mother, or the father or adopting father, as the case may be, of such person went through a marriage ceremony resulting in a purported marriage between them which, but for a legal impediment described in the last sentence of subsection (h)(1)(B), would have been a valid marriage. For purposes of clause (2), a child shall be deemed to have been the stepchild of an individual for a period of one year throughout the month in which occurs the expiration of such one year. For purposes of clause (3), a person shall be deemed to have no natural or adoptive parent living (other than a parent who was under a disability) throughout the most recent month in which a natural or adoptive parent (not under a disability) dies."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/416?type=usc&year=mostrecent&link-type=html"},"op":4,"ar":1,"head":"§416. Additional definitions","tname":"The Public Health and Welfare","by":{"0":"7, 13, passim, 8, 10, 11, 12, 18, 23, 2, 12, 12, passim, 15, 16, 14, 15, 10, 15, 25, passim, 8, 10, 14, 15, 23, 9, 15, 25, passim, 8, 23, 8, 23"}},{"t":"usc","label":"42 U.S.C. § 902","url":"https://www.law.cornell.edu/uscode/text/42/902","subs":["(a)(5)"],"by":{"0":"24"}},{"t":"law","label":"Pub. L. No. 86-778","url":"https://www.govinfo.gov/link/statute/74/924","by":{"0":"17"}},{"t":"usc","label":"5 U.S.C. § 8341","url":"https://www.law.cornell.edu/uscode/text/5/8341","subs":["(e)(2)"],"by":{"0":"12"}},{"t":"reg","label":"5 Fed. Reg. 1880","url":"https://www.govinfo.gov/link/fr/5/1880","by":{"0":"24"}}]};